// BERKAS HASIL OLAHAN: font dan logo untuk pembuat gambar di server.
// Disematkan sebagai teks supaya selalu ikut terpasang di Vercel (tidak bergantung pada berkas lain).
// Font: Bricolage Grotesque dan Public Sans (lisensi SIL Open Font License), subset huruf Latin.

function dariBase64(b64: string): ArrayBuffer {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes.buffer;
}

const bricolage800 = "";
const bricolage700 = "";
const publicSans500 = "";
const publicSans700 = "";

export const FONT = {
  bricolage800: dariBase64(bricolage800),
  bricolage700: dariBase64(bricolage700),
  publicSans500: dariBase64(publicSans500),
  publicSans700: dariBase64(publicSans700),
};

export const LOGO_IPNU = "data:image/png;base64,";
export const LOGO_IPPNU = "data:image/png;base64,";
